const cfg = $('Config').first().json;
const prompt = $('Brand Stylist').first().json.choices[0].message.content.trim();
const model = cfg.FAL_MODEL;
const headers = { 'Authorization': 'Key ' + cfg.FAL_KEY, 'Content-Type': 'application/json' };

// 1) submit job to fal queue
const submit = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://queue.fal.run/' + model,
  headers,
  body: {
    prompt: prompt,
    resolution: cfg.resolution,
    duration: String(cfg.duration),
    aspect_ratio: cfg.aspectRatio,
    generate_audio: true
  },
  json: true
});

const statusUrl = submit.status_url;
const responseUrl = submit.response_url;

// 2) poll until done (5s interval, ~7.5 min max)
let st = {};
for (let i = 0; i < 90; i++) {
  await new Promise(r => setTimeout(r, 5000));
  st = await this.helpers.httpRequest({ method: 'GET', url: statusUrl, headers, json: true });
  if (st.status === 'COMPLETED') break;
  if (st.status === 'FAILED' || st.status === 'ERROR') {
    throw new Error('fal job failed: ' + JSON.stringify(st));
  }
}

// 3) fetch the final result
const res = await this.helpers.httpRequest({ method: 'GET', url: responseUrl, headers, json: true });

return [{ json: {
  videoUrl: (res.video || {}).url,
  seed: res.seed,
  requestId: submit.request_id,
  finalPrompt: prompt
} }];
